INSERT OR IGNORE INTO artist_appearances (id,slug,title,summary,description,starts_at,ends_at,timezone,lifecycle_status,formats_json,participation_roles_json,ticket_url,source_url,state,sort_order,created_at,updated_at) VALUES
('appearance-sfqp-artist-talk-2019','sfqp-artist-talk-2019','SFQP Artist Talk','An artist talk presented by Southern Fried Queer Pride at Atlanta Contemporary.','Saiel Dauhn Solehman discussed her work and experience as a working professional. The July 11, 2019 announcement credits her as Saiel Solomon. Atlanta Contemporary also lists her under Partner Artist; the historical credit belongs to the same artist and continuing practice.','2019-07-11T22:00:00Z','2019-07-12T00:00:00Z','America/New_York','completed','["Artist talk"]','["Speaker"]','','https://archive.atlantacontemporary.org/events/sfqp-artist-talk','published',10,datetime('now'),datetime('now'));
INSERT INTO archive_dossiers (entity_id,archive_slug,orientation,story,story_html,empty_materials_note,record_type,state,public_visible,featured,sort_order,published_at,created_by,updated_by,created_at,updated_at) VALUES
('appearance-sfqp-artist-talk-2019','sfqp-artist-talk-2019','SFQP Artist Talk, July 11, 2019, at Atlanta Contemporary.','Presented by Southern Fried Queer Pride, 6–8 p.m. Atlanta time. Historical credit: Saiel Solomon. Current artist: Saiel Dauhn Solehman. Atlanta Contemporary categorizes the artist as Partner Artist in its archived profile and people index. This listing does not establish a residency or an ongoing contractual partnership.','<p>Presented by Southern Fried Queer Pride on July 11, 2019, 6–8 p.m., at Atlanta Contemporary.</p><p>Historical credit: Saiel Solomon. This is the former name of <a href="/about/saieldauhnsolehman/">Saiel Dauhn Solehman</a>.</p><h2>Partner Artist listing</h2><p>Atlanta Contemporary categorizes the artist as Partner Artist in its <a href="https://archive.atlantacontemporary.org/people/saiel-solomon">historical artist profile</a> and <a href="https://archive.atlantacontemporary.org/search-index?section=people&amp;category=partner-artist">Partner Artist index</a>. Both listings refer to <a href="/about/saieldauhnsolehman/">Saiel Dauhn Solehman</a>.</p><p><a href="https://archive.atlantacontemporary.org/events/sfqp-artist-talk">Original event listing</a></p>','Photographs remain available through the original event listing.','event','published',1,0,10,datetime('now'),'migration-0244','migration-0244',datetime('now'),datetime('now')) ON CONFLICT(entity_id) DO UPDATE SET archive_slug=excluded.archive_slug,orientation=excluded.orientation,story=excluded.story,story_html=excluded.story_html,empty_materials_note=excluded.empty_materials_note,record_type=excluded.record_type,state=excluded.state,public_visible=excluded.public_visible,published_at=excluded.published_at,updated_by=excluded.updated_by,updated_at=excluded.updated_at WHERE archive_dossiers.story='' AND archive_dossiers.story_html='';
