INSERT OR IGNORE INTO archive_materials (id,dossier_entity_id,role,material_type,title,body,date_precision,date_label,visibility,state,sort_order,created_by,updated_by,created_at,updated_at) VALUES
('source-atlanta-contemporary-partner-artist','appearance-sfqp-artist-talk-2019','institutional-listing','document','Atlanta Contemporary — Partner Artist listing','Atlanta Contemporary lists Saiel Solomon, the former name of Saiel Dauhn Solehman, as Partner Artist. Current profile: /about/saieldauhnsolehman/ . Historical profile: https://archive.atlantacontemporary.org/people/saiel-solomon . Index: https://archive.atlantacontemporary.org/search-index?section=people&category=partner-artist . Verified October 22, 2026; the listing supplies no partnership dates.','undated','Historical listing; dates unspecified','public','published',1,'migration-0244','migration-0244',datetime('now'),datetime('now'));
